use crate::scene::*;
#[derive(Clone)]pub struct View{pub yaw:f64,pub pitch:f64,pub zoom:f64,pub pan:[f64;2]}
impl Default for View{fn default()->Self{Self{yaw:-45.,pitch:30.,zoom:1.,pan:[0.;2]}}}
pub struct Frame{pub w:usize,pub h:usize,pub rgb:Vec<[u8;3]>,pub ids:Vec<Option<(usize,usize)>>,z:Vec<f64>}
impl Frame{
 pub fn new(w:usize,h:usize)->Self{Self{w,h,rgb:vec![[12,14,18];w*h],ids:vec![None;w*h],z:vec![f64::NEG_INFINITY;w*h]}}
 fn tri(&mut self,a:V,b:V,c:V,col:[u8;3],id:(usize,usize)){let edge=|a:V,b:V,x:f64,y:f64|(b[0]-a[0])*(y-a[1])-(b[1]-a[1])*(x-a[0]);let area=edge(a,b,c[0],c[1]);if area.abs()<1e-10{return}let lo=|i:usize|a[i].min(b[i]).min(c[i]).floor().max(0.) as usize;let hi=|i:usize,limit:usize|a[i].max(b[i]).max(c[i]).ceil().clamp(0.,limit as f64)as usize;for y in lo(1)..hi(1,self.h){for x in lo(0)..hi(0,self.w){let u=edge(b,c,x as f64+0.5,y as f64+0.5)/area;let v=edge(c,a,x as f64+0.5,y as f64+0.5)/area;let t=1.-u-v;if u>=-1e-9&&v>=-1e-9&&t>=-1e-9{let z=u*a[2]+v*b[2]+t*c[2];let k=y*self.w+x;if z>self.z[k]{self.z[k]=z;self.rgb[k]=col;self.ids[k]=Some(id)}}}}}
 pub fn rows(&self)->Vec<String>{let mut rows=vec![];for y in (0..self.h).step_by(2){let mut s=String::new();let mut prev=None;for x in 0..self.w{let a=self.rgb[y*self.w+x];let b=self.rgb[(y+1).min(self.h-1)*self.w+x];if prev!=Some((a,b)){s.push_str(&format!("\x1b[38;2;{};{};{};48;2;{};{};{}m",a[0],a[1],a[2],b[0],b[1],b[2]));prev=Some((a,b))}s.push('▀')}s.push_str("\x1b[0m");rows.push(s)}rows}
}
pub fn render(s:&Scene,v:&View,w:usize,h:usize,selected:Option<usize>,face:Option<usize>)->Frame{let mut f=Frame::new(w,h);let mut lo=[f64::INFINITY;3];let mut hi=[f64::NEG_INFINITY;3];for p in s.objects.iter().flat_map(|o|&o.p){for i in 0..3{lo[i]=lo[i].min(p[i]);hi[i]=hi[i].max(p[i]);}}if !lo[0].is_finite(){return f}let c=[(lo[0]+hi[0])/2.,(lo[1]+hi[1])/2.,(lo[2]+hi[2])/2.];let span=dot(sub(hi,lo),sub(hi,lo)).sqrt().max(0.01);let scale=w.min(h)as f64*0.85/span*v.zoom;for (oi,o) in s.objects.iter().enumerate(){let p:Vec<V>=o.p.iter().map(|&p|{let q=rotate(rotate(sub(p,c),1,v.yaw.to_radians()),0,v.pitch.to_radians());[q[0]*scale+w as f64/2.+v.pan[0],-q[1]*scale+h as f64/2.+v.pan[1],q[2]]}).collect();for (fi,face_) in o.f.iter().enumerate(){let a=p[face_.v[0]];let b=p[face_.v[1]];let c=p[face_.v[2]];let n=norm(cross(sub(b,a),sub(c,a)));let light=0.30+0.70*dot(n,norm([0.35,0.8,0.48])).max(0.);let col=if selected==Some(oi)&&face==Some(fi){[255,165,45]}else{face_.color.map(|x|(x as f64*light)as u8)};for k in 1..face_.v.len()-1{f.tri(a,p[face_.v[k]],p[face_.v[k+1]],col,(oi,fi));}}}f}
#[cfg(test)]mod tests{use super::*;#[test]fn cube(){let s=Scene{objects:vec![Object::cube("cube".into(),[220,100,40])]};let f=render(&s,&View::default(),80,40,None,None);assert!(f.ids.iter().filter(|x|x.is_some()).count()>100);assert_eq!(f.rows().len(),20);assert!(f.ids[0].is_none());}}
